namespace QualityReporter.CSharp.Analysis.Axes;
public interface IQualityAxisCalculator { QualityAxisScore Calculate(IReadOnlyDictionary<string,double?> components); }
public abstract class QualityAxisCalculator(IReadOnlyDictionary<string,double> weights,bool enabled=true):IQualityAxisCalculator { public QualityAxisScore Calculate(IReadOnlyDictionary<string,double?> components){if(!enabled)return Unknown();var available=components.Where(x=>x.Value.HasValue&&weights.GetValueOrDefault(x.Key)>0).ToList();var total=available.Sum(x=>weights[x.Key]);if(total<=0)return Unknown();var values=available.ToDictionary(x=>x.Key,x=>Math.Clamp(x.Value!.Value,0,100));var score=Math.Round(available.Sum(x=>x.Value!.Value*weights[x.Key])/total,1);return new(){Score=score,Level=Level(score),Components=values,AvailableWeight=total};} public static string Level(double? score,bool activity=false)=>!score.HasValue?"unknown":activity?(score>=70?"high":score>=40?"medium":"low"):(score>=80?"critical":score>=60?"high":score>=40?"medium":"low"); public static QualityAxisScore Unknown()=>new(); }
